style.css:
/* CUSTOM STYLISH PHOTO THEME */

body {
  background:
    linear-gradient(
      135deg,
      rgba(15, 10, 25, 0.35),
      rgba(45, 20, 70, 0.55)
    ),
    url("https://cdn.phototourl.com/member/2026-10-24-c9f0da56-c10c-4b2f-a8e2-05ff4d68e7ac.jpg")
    center / cover fixed no-repeat !important;

  color: #ffffff !important;
  min-height: 100vh !important;
}

/* Purple accents */
button,
input,
select {
  accent-color: #c29aff !important;
}

/* Smooth transitions */
* {
  transition: background-color 0.2s ease;
}
